window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-905e61b911620c04"]={"versions": [{"id": "FIG-905e61b911620c04", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Funktionales Blockdiagramm / Dekompositionsdiagramm der Anwendungsarchitektur (AUTOSAR Application Layer Decomposition).</li>\n<li><strong>Funktionale Einordnung:</strong> Detaillierung der Subdomäne Verbrennungsmotor (<em>Combustion Engine</em>) im Kontext des Dokuments <code>AUTOSAR_EXP_AIPowertrain</code> (R4.0.3). Es definiert die standardisierte funktionale Zerlegung und die Schnittstellen-Entkopplung zwischen der übergeordneten Antriebsstrangkoordination (<em>Power Train Coordinator</em>) und den motorspezifischen Teilsystemen zur Drehmoment-, Drehzahl- und Modusführung.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Funktionsblöcke</p>\n<ul class=\"fig-list\">\n<li><strong><code>Power Train Coordinator</code> (PT Coordinator):</strong></li>\n</ul>\n<p class=\"fig-p\">Übergeordnete Koordinationsinstanz für Priorisierung, Optimierung und Verteilung fahrzeugweiter Anforderungen. Beinhaltet drei logische Funktionseinheiten:</p>\n<ul class=\"fig-list\">\n<li><code>PT Torque Coordinator</code>: Schiedsstelle für alle Drehmomentanforderungen (Fahrerwunsch, Fahrwerk/ESP, Getriebe, ACC).</li>\n<li><code>PT Speed Coordinator</code>: Schiedsstelle für Solldrehzahlen (z. B. Leerlaufregelung, Anlassvorgang, Getriebeeingriffe).</li>\n<li><code>PT Operation Mode</code>: Zustandsverwaltung des Gesamtantriebsstrangs (Stopp, Start, Übergangs- und Notlaufmodi).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>Combustion Engine</code> (Domain-Composition):</strong></li>\n</ul>\n<p class=\"fig-p\">Zusammenfassung aller innermotorischen Software-Komponenten (<code>SW-C</code>).</p>\n<ul class=\"fig-list\">\n<li><code>Engine torque &amp; mode management</code>: Zentraler Aggregatsmanager; empfängt und arbitriert die Anforderungen des PT Coordinators und splittet diese in motorische Stellpfade.</li>\n<li>Stellpfad-Subsysteme:</li>\n<li><code>Air system</code>: Steuerung des Füllungspfads (Drosselklappe, variable Steuerzeiten/VVT, Ladedruckregelung, AGR).</li>\n<li><code>Fuel system</code>: Gemischbildung und Einspritzsteuerung (Raildruck, Einspritzzeitpunkt/-dauer, Mehrfacheinspritzung).</li>\n<li><code>Ignition system</code>: Zündungsregelung (Zündzeitpunkt, Schließwinkel/Dwell Time, Zündenergie).</li>\n<li>Autarke/unterstützende Motorsystem-SW-Cs:</li>\n<li><code>Combustion</code>: Zylinderdruckanalyse, Klopfregelung, Verbrennungsdiagnose.</li>\n<li><code>Glow system</code>: Glühzeitsteuerung (insb. Dieselapplikation).</li>\n<li><code>Exhaust system</code>: Abgasnachbehandlung (SCR, Partikelfilter, Katalysatorheizen, Lambdaregelung).</li>\n<li><code>Engine position and speed</code>: Signalverarbeitung Kurbel-/Nockenwelle, Phasenerkennung, Kurbelwinkel-Synchronisation.</li>\n<li><code>Engine Lubrication</code>: Öldruck- und Ölpumpenmanagement.</li>\n<li><code>Engine Temperature</code>: Erfassung und Regelung der innermotorischen thermischen Zustände.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>Thermal management</code> (Externes Subsystem):</strong></li>\n</ul>\n<p class=\"fig-p\">Fahrzeugweites Thermomanagement (Aktoren: <em>water pump</em>, <em>climate compr.</em>); Schnittstelle zur Komponente <code>Engine Temperature</code>.</p>\n<p class=\"fig-p\">#### Schnittstellen & Kommunikationsbeziehungen</p>\n<ul class=\"fig-list\">\n<li><strong>PT Coordinator $\\rightarrow$ Combustion Engine (<code>Engine torque &amp; mode management</code>):</strong></li>\n<li><code>Engine Torque Requests</code>: Sender-Receiver-Schnittstelle zur Übertragung koordinierter Drehmoment-Sollwerte (typisch: physikalische Drehmomentstruktur in Nm, Min-/Max-Grenzen, Prioritäten).</li>\n<li><code>Engine Speed set-point</code>: Sender-Receiver-Schnittstelle für Soll-Drehzahlen.</li>\n<li><code>Engine Mode Request(s)</code>: Mode-Switch- oder Sender-Receiver-Schnittstelle zur Vorgabe diskreter Motorbetriebsmodi.</li>\n<li><strong><code>Engine torque &amp; mode management</code> $\\rightarrow$ Aktuatorpfade:</strong></li>\n<li>Gerichtet aufgeteilt in <code>Air system</code> (langsamer Drehmomentpfad / Füllung), <code>Fuel system</code> und <code>Ignition system</code> (schnelle Drehmomentpfade / Zündwinkel- und Einspritzwirkungsgrad).</li>\n<li><strong><code>Thermal management</code> $\\rightarrow$ <code>Engine Temperature</code>:</strong></li>\n<li>Unidirektionaler Datenfluss zur Abstimmung der Kühlmittelflussanforderungen und Berücksichtigung von thermischen Lastgrenzen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Sollwert-Vorgabe (zyklisch, zeitsynchron, typisch 10 ms):</strong></li>\n</ol>\n<p class=\"fig-p\"><code>PT Torque Coordinator</code>, <code>PT Speed Coordinator</code> und <code>PT Operation Mode</code> konsolidieren externe Anforderungen und stellen konsistente Solldaten an den Ports bereit.</p>\n<ol class=\"fig-list\">\n<li><strong>Arbitrierung & Strukturierung (zeitsynchron):</strong></li>\n</ol>\n<p class=\"fig-p\"><code>Engine torque &amp; mode management</code> empfängt die Anforderungen über die AUTOSAR-RTE, wendet motorspezifische Schutz- und Emissionsbegrenzungen an und teilt das Zieldrehmoment auf:</p>\n<ul class=\"fig-list\">\n<li><em>Langsamer Pfad:</em> Vorsteuerung und Sollwertberechnung für das <code>Air system</code> zur Bereitstellung der Zylinderfüllung.</li>\n<li><em>Schneller Pfad:</em> Dynamische Momentenkorrekturen direkt über <code>Fuel system</code> (Ausblendung, Einspritzmenge) und <code>Ignition system</code> (Zündwinkelverstellung nach spät).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisation mit Motorzyklus (ereignisgesteuert / kurbelwinkelsynchron):</strong></li>\n</ol>\n<p class=\"fig-p\"><code>Engine position and speed</code> generiert Drehzahlinformationen und Segment-/OT-Interrupts. Die Komponenten <code>Fuel system</code> und <code>Ignition system</code> synchronisieren die Ausgabe der Steuerzeiten winkelsynchron zu den Kurbelwellensegmenten.</p>\n<ol class=\"fig-list\">\n<li><strong>Thermisches Feedback:</strong></li>\n</ol>\n<p class=\"fig-p\"><code>Thermal management</code> und <code>Engine Temperature</code> tauschen kontinuierlich Grenzwerte und Leistungsanforderungen aus, um Bauteilschutzfunktionen (Derating) im Momentenpfad auszulösen.</p>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Status der Spezifikation:</strong> <code>AUTOSAR_EXP_AIPowertrain</code> ist ein informativer Erläuterungsbericht (Explanation, <em>EXP</em>), keine normative Software-Spezifikation (<em>SWS</em>). Die Komponentenaufteilung dient als herstellerübergreifende Referenzarchitektur für AUTOSAR Application Interfaces (<code>AI</code>).</li>\n<li><strong>SW-C-Implementierung & Port-Typen:</strong></li>\n<li><code>Engine torque &amp; mode management</code> ist als <code>ApplicationSwComponentType</code> zu modellieren. Die Eingangsschnittstellen (<code>Engine Torque Requests</code>, <code>Engine Speed set-point</code>) basieren auf <code>SenderReceiverInterface</code>.</li>\n<li><code>Engine Mode Request(s)</code> ist bevorzugt als <code>ModeSwitchInterface</code> unter Verwendung definierter <code>ModeDeclarationGroups</code> auszugestalten.</li>\n<li><strong>Echtzeit- und BSW-Konfiguration (MCAL/CDD):</strong></li>\n<li>Die Komponenten <code>Engine position and speed</code>, <code>Fuel system</code> und <code>Ignition system</code> können aufgrund harter Winkelsynchronität und Latenzanforderungen (< 10 µs) in der Regel nicht rein über den Standard-MCAL-Stack (GPT/ICU/PWM) abgebildet werden.</li>\n<li>Entwickler müssen diese Pfade typischerweise an <code>Complex Device Drivers</code> (CDD) oder dedizierte Timer-Coprogressoren (z. B. Bosch GTM, Freescale eTPU) anbinden.</li>\n<li><strong>Multi-Core-Partitionierung:</strong></li>\n</ul>\n<p class=\"fig-p\">Zur Vermeidung von Race Conditions und Dateninkonsistenzen (Data Consistency via RTE) muss die Zerlegung zwischen dem zeitsynchronen Momentenmanagement (<code>Engine torque &amp; mode management</code>) und den winkelsynchronen Aktuator-SW-Cs über Inter-Runnable-Variables (<code>IRV</code>) oder gepufferte RTE-Kommunikation (<code>Queued/Implicit Buffer</code>) thread-sicher ausgelegt werden.</p>"}, {"id": "FIG-741895c783a5a6b0", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Funktionales Blockdiagramm / Dekompositionsdiagramm der Anwendungsarchitektur (AUTOSAR Application Layer Decomposition).</li>\n<li><strong>Funktionale Einordnung:</strong> Detaillierung der Subdomäne Verbrennungsmotor (<em>Combustion Engine</em>) im Kontext des Dokuments <code>AUTOSAR_EXP_AIPowertrain</code> (R4.0.3). Es definiert die standardisierte funktionale Zerlegung und die Schnittstellen-Entkopplung zwischen der übergeordneten Antriebsstrangkoordination (<em>Power Train Coordinator</em>) und den motorspezifischen Teilsystemen zur Drehmoment-, Drehzahl- und Modusführung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Funktionsblöcke</p>\n<ul class=\"fig-list\">\n<li><strong><code>Power Train Coordinator</code> (PT Coordinator):</strong></li>\n</ul>\n<p class=\"fig-p\">Übergeordnete Koordinationsinstanz für Priorisierung, Optimierung und Verteilung fahrzeugweiter Anforderungen. Beinhaltet drei logische Funktionseinheiten:</p>\n<ul class=\"fig-list\">\n<li><code>PT Torque Coordinator</code>: Schiedsstelle für alle Drehmomentanforderungen (Fahrerwunsch, Fahrwerk/ESP, Getriebe, ACC).</li>\n<li><code>PT Speed Coordinator</code>: Schiedsstelle für Solldrehzahlen (z. B. Leerlaufregelung, Anlassvorgang, Getriebeeingriffe).</li>\n<li><code>PT Operation Mode</code>: Zustandsverwaltung des Gesamtantriebsstrangs (Stopp, Start, Übergangs- und Notlaufmodi).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>Combustion Engine</code> (Domain-Composition):</strong></li>\n</ul>\n<p class=\"fig-p\">Zusammenfassung aller innermotorischen Software-Komponenten (<code>SW-C</code>).</p>\n<ul class=\"fig-list\">\n<li><code>Engine torque &amp; mode management</code>: Zentraler Aggregatsmanager; empfängt und arbitriert die Anforderungen des PT Coordinators und splittet diese in motorische Stellpfade.</li>\n<li>Stellpfad-Subsysteme:</li>\n<li><code>Air system</code>: Steuerung des Füllungspfads (Drosselklappe, variable Steuerzeiten/VVT, Ladedruckregelung, AGR).</li>\n<li><code>Fuel system</code>: Gemischbildung und Einspritzsteuerung (Raildruck, Einspritzzeitpunkt/-dauer, Mehrfacheinspritzung).</li>\n<li><code>Ignition system</code>: Zündungsregelung (Zündzeitpunkt, Schließwinkel/Dwell Time, Zündenergie).</li>\n<li>Autarke/unterstützende Motorsystem-SW-Cs:</li>\n<li><code>Combustion</code>: Zylinderdruckanalyse, Klopfregelung, Verbrennungsdiagnose.</li>\n<li><code>Glow system</code>: Glühzeitsteuerung (insb. Dieselapplikation).</li>\n<li><code>Exhaust system</code>: Abgasnachbehandlung (SCR, Partikelfilter, Katalysatorheizen, Lambdaregelung).</li>\n<li><code>Engine position and speed</code>: Signalverarbeitung Kurbel-/Nockenwelle, Phasenerkennung, Kurbelwinkel-Synchronisation.</li>\n<li><code>Engine Lubrication</code>: Öldruck- und Ölpumpenmanagement.</li>\n<li><code>Engine Temperature</code>: Erfassung und Regelung der innermotorischen thermischen Zustände.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>Thermal management</code> (Externes Subsystem):</strong></li>\n</ul>\n<p class=\"fig-p\">Fahrzeugweites Thermomanagement (Aktoren: <em>water pump</em>, <em>climate compr.</em>); Schnittstelle zur Komponente <code>Engine Temperature</code>.</p>\n<p class=\"fig-p\">#### Schnittstellen & Kommunikationsbeziehungen</p>\n<ul class=\"fig-list\">\n<li><strong>PT Coordinator $\\rightarrow$ Combustion Engine (<code>Engine torque &amp; mode management</code>):</strong></li>\n<li><code>Engine Torque Requests</code>: Sender-Receiver-Schnittstelle zur Übertragung koordinierter Drehmoment-Sollwerte (typisch: physikalische Drehmomentstruktur in Nm, Min-/Max-Grenzen, Prioritäten).</li>\n<li><code>Engine Speed set-point</code>: Sender-Receiver-Schnittstelle für Soll-Drehzahlen.</li>\n<li><code>Engine Mode Request(s)</code>: Mode-Switch- oder Sender-Receiver-Schnittstelle zur Vorgabe diskreter Motorbetriebsmodi.</li>\n<li><strong><code>Engine torque &amp; mode management</code> $\\rightarrow$ Aktuatorpfade:</strong></li>\n<li>Gerichtet aufgeteilt in <code>Air system</code> (langsamer Drehmomentpfad / Füllung), <code>Fuel system</code> und <code>Ignition system</code> (schnelle Drehmomentpfade / Zündwinkel- und Einspritzwirkungsgrad).</li>\n<li><strong><code>Thermal management</code> $\\rightarrow$ <code>Engine Temperature</code>:</strong></li>\n<li>Unidirektionaler Datenfluss zur Abstimmung der Kühlmittelflussanforderungen und Berücksichtigung von thermischen Lastgrenzen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Sollwert-Vorgabe (zyklisch, zeitsynchron, typisch 10 ms):</strong></li>\n</ol>\n<p class=\"fig-p\"><code>PT Torque Coordinator</code>, <code>PT Speed Coordinator</code> und <code>PT Operation Mode</code> konsolidieren externe Anforderungen und stellen konsistente Solldaten an den Ports bereit.</p>\n<ol class=\"fig-list\">\n<li><strong>Arbitrierung & Strukturierung (zeitsynchron):</strong></li>\n</ol>\n<p class=\"fig-p\"><code>Engine torque &amp; mode management</code> empfängt die Anforderungen über die AUTOSAR-RTE, wendet motorspezifische Schutz- und Emissionsbegrenzungen an und teilt das Zieldrehmoment auf:</p>\n<ul class=\"fig-list\">\n<li><em>Langsamer Pfad:</em> Vorsteuerung und Sollwertberechnung für das <code>Air system</code> zur Bereitstellung der Zylinderfüllung.</li>\n<li><em>Schneller Pfad:</em> Dynamische Momentenkorrekturen direkt über <code>Fuel system</code> (Ausblendung, Einspritzmenge) und <code>Ignition system</code> (Zündwinkelverstellung nach spät).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisation mit Motorzyklus (ereignisgesteuert / kurbelwinkelsynchron):</strong></li>\n</ol>\n<p class=\"fig-p\"><code>Engine position and speed</code> generiert Drehzahlinformationen und Segment-/OT-Interrupts. Die Komponenten <code>Fuel system</code> und <code>Ignition system</code> synchronisieren die Ausgabe der Steuerzeiten winkelsynchron zu den Kurbelwellensegmenten.</p>\n<ol class=\"fig-list\">\n<li><strong>Thermisches Feedback:</strong></li>\n</ol>\n<p class=\"fig-p\"><code>Thermal management</code> und <code>Engine Temperature</code> tauschen kontinuierlich Grenzwerte und Leistungsanforderungen aus, um Bauteilschutzfunktionen (Derating) im Momentenpfad auszulösen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Status der Spezifikation:</strong> <code>AUTOSAR_EXP_AIPowertrain</code> ist ein informativer Erläuterungsbericht (Explanation, <em>EXP</em>), keine normative Software-Spezifikation (<em>SWS</em>). Die Komponentenaufteilung dient als herstellerübergreifende Referenzarchitektur für AUTOSAR Application Interfaces (<code>AI</code>).</li>\n<li><strong>SW-C-Implementierung & Port-Typen:</strong></li>\n<li><code>Engine torque &amp; mode management</code> ist als <code>ApplicationSwComponentType</code> zu modellieren. Die Eingangsschnittstellen (<code>Engine Torque Requests</code>, <code>Engine Speed set-point</code>) basieren auf <code>SenderReceiverInterface</code>.</li>\n<li><code>Engine Mode Request(s)</code> ist bevorzugt als <code>ModeSwitchInterface</code> unter Verwendung definierter <code>ModeDeclarationGroups</code> auszugestalten.</li>\n<li><strong>Echtzeit- und BSW-Konfiguration (MCAL/CDD):</strong></li>\n<li>Die Komponenten <code>Engine position and speed</code>, <code>Fuel system</code> und <code>Ignition system</code> können aufgrund harter Winkelsynchronität und Latenzanforderungen (< 10 µs) in der Regel nicht rein über den Standard-MCAL-Stack (GPT/ICU/PWM) abgebildet werden.</li>\n<li>Entwickler müssen diese Pfade typischerweise an <code>Complex Device Drivers</code> (CDD) oder dedizierte Timer-Coprogressoren (z. B. Bosch GTM, Freescale eTPU) anbinden.</li>\n<li><strong>Multi-Core-Partitionierung:</strong></li>\n</ul>\n<p class=\"fig-p\">Zur Vermeidung von Race Conditions und Dateninkonsistenzen (Data Consistency via RTE) muss die Zerlegung zwischen dem zeitsynchronen Momentenmanagement (<code>Engine torque &amp; mode management</code>) und den winkelsynchronen Aktuator-SW-Cs über Inter-Runnable-Variables (<code>IRV</code>) oder gepufferte RTE-Kommunikation (<code>Queued/Implicit Buffer</code>) thread-sicher ausgelegt werden.</p>"}, {"id": "FIG-38ad329e6f7ab9b1", "releases": ["R4.2.2", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Funktionales Blockdiagramm / Dekompositionsdiagramm der Anwendungsarchitektur (AUTOSAR Application Layer Decomposition).</li>\n<li><strong>Funktionale Einordnung:</strong> Detaillierung der Subdomäne Verbrennungsmotor (<em>Combustion Engine</em>) im Kontext des Dokuments <code>AUTOSAR_EXP_AIPowertrain</code> (R4.0.3). Es definiert die standardisierte funktionale Zerlegung und die Schnittstellen-Entkopplung zwischen der übergeordneten Antriebsstrangkoordination (<em>Power Train Coordinator</em>) und den motorspezifischen Teilsystemen zur Drehmoment-, Drehzahl- und Modusführung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Funktionsblöcke</p>\n<ul class=\"fig-list\">\n<li><strong><code>Power Train Coordinator</code> (PT Coordinator):</strong></li>\n</ul>\n<p class=\"fig-p\">Übergeordnete Koordinationsinstanz für Priorisierung, Optimierung und Verteilung fahrzeugweiter Anforderungen. Beinhaltet drei logische Funktionseinheiten:</p>\n<ul class=\"fig-list\">\n<li><code>PT Torque Coordinator</code>: Schiedsstelle für alle Drehmomentanforderungen (Fahrerwunsch, Fahrwerk/ESP, Getriebe, ACC).</li>\n<li><code>PT Speed Coordinator</code>: Schiedsstelle für Solldrehzahlen (z. B. Leerlaufregelung, Anlassvorgang, Getriebeeingriffe).</li>\n<li><code>PT Operation Mode</code>: Zustandsverwaltung des Gesamtantriebsstrangs (Stopp, Start, Übergangs- und Notlaufmodi).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>Combustion Engine</code> (Domain-Composition):</strong></li>\n</ul>\n<p class=\"fig-p\">Zusammenfassung aller innermotorischen Software-Komponenten (<code>SW-C</code>).</p>\n<ul class=\"fig-list\">\n<li><code>Engine torque &amp; mode management</code>: Zentraler Aggregatsmanager; empfängt und arbitriert die Anforderungen des PT Coordinators und splittet diese in motorische Stellpfade.</li>\n<li>Stellpfad-Subsysteme:</li>\n<li><code>Air system</code>: Steuerung des Füllungspfads (Drosselklappe, variable Steuerzeiten/VVT, Ladedruckregelung, AGR).</li>\n<li><code>Fuel system</code>: Gemischbildung und Einspritzsteuerung (Raildruck, Einspritzzeitpunkt/-dauer, Mehrfacheinspritzung).</li>\n<li><code>Ignition system</code>: Zündungsregelung (Zündzeitpunkt, Schließwinkel/Dwell Time, Zündenergie).</li>\n<li>Autarke/unterstützende Motorsystem-SW-Cs:</li>\n<li><code>Combustion</code>: Zylinderdruckanalyse, Klopfregelung, Verbrennungsdiagnose.</li>\n<li><code>Glow system</code>: Glühzeitsteuerung (insb. Dieselapplikation).</li>\n<li><code>Exhaust system</code>: Abgasnachbehandlung (SCR, Partikelfilter, Katalysatorheizen, Lambdaregelung).</li>\n<li><code>Engine position and speed</code>: Signalverarbeitung Kurbel-/Nockenwelle, Phasenerkennung, Kurbelwinkel-Synchronisation.</li>\n<li><code>Engine Lubrication</code>: Öldruck- und Ölpumpenmanagement.</li>\n<li><code>Engine Temperature</code>: Erfassung und Regelung der innermotorischen thermischen Zustände.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>Thermal management</code> (Externes Subsystem):</strong></li>\n</ul>\n<p class=\"fig-p\">Fahrzeugweites Thermomanagement (Aktoren: <em>water pump</em>, <em>climate compr.</em>); Schnittstelle zur Komponente <code>Engine Temperature</code>.</p>\n<p class=\"fig-p\">#### Schnittstellen & Kommunikationsbeziehungen</p>\n<ul class=\"fig-list\">\n<li><strong>PT Coordinator $\\rightarrow$ Combustion Engine (<code>Engine torque &amp; mode management</code>):</strong></li>\n<li><code>Engine Torque Requests</code>: Sender-Receiver-Schnittstelle zur Übertragung koordinierter Drehmoment-Sollwerte (typisch: physikalische Drehmomentstruktur in Nm, Min-/Max-Grenzen, Prioritäten).</li>\n<li><code>Engine Speed set-point</code>: Sender-Receiver-Schnittstelle für Soll-Drehzahlen.</li>\n<li><code>Engine Mode Request(s)</code>: Mode-Switch- oder Sender-Receiver-Schnittstelle zur Vorgabe diskreter Motorbetriebsmodi.</li>\n<li><strong><code>Engine torque &amp; mode management</code> $\\rightarrow$ Aktuatorpfade:</strong></li>\n<li>Gerichtet aufgeteilt in <code>Air system</code> (langsamer Drehmomentpfad / Füllung), <code>Fuel system</code> und <code>Ignition system</code> (schnelle Drehmomentpfade / Zündwinkel- und Einspritzwirkungsgrad).</li>\n<li><strong><code>Thermal management</code> $\\rightarrow$ <code>Engine Temperature</code>:</strong></li>\n<li>Unidirektionaler Datenfluss zur Abstimmung der Kühlmittelflussanforderungen und Berücksichtigung von thermischen Lastgrenzen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Sollwert-Vorgabe (zyklisch, zeitsynchron, typisch 10 ms):</strong></li>\n</ol>\n<p class=\"fig-p\"><code>PT Torque Coordinator</code>, <code>PT Speed Coordinator</code> und <code>PT Operation Mode</code> konsolidieren externe Anforderungen und stellen konsistente Solldaten an den Ports bereit.</p>\n<ol class=\"fig-list\">\n<li><strong>Arbitrierung & Strukturierung (zeitsynchron):</strong></li>\n</ol>\n<p class=\"fig-p\"><code>Engine torque &amp; mode management</code> empfängt die Anforderungen über die AUTOSAR-RTE, wendet motorspezifische Schutz- und Emissionsbegrenzungen an und teilt das Zieldrehmoment auf:</p>\n<ul class=\"fig-list\">\n<li><em>Langsamer Pfad:</em> Vorsteuerung und Sollwertberechnung für das <code>Air system</code> zur Bereitstellung der Zylinderfüllung.</li>\n<li><em>Schneller Pfad:</em> Dynamische Momentenkorrekturen direkt über <code>Fuel system</code> (Ausblendung, Einspritzmenge) und <code>Ignition system</code> (Zündwinkelverstellung nach spät).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisation mit Motorzyklus (ereignisgesteuert / kurbelwinkelsynchron):</strong></li>\n</ol>\n<p class=\"fig-p\"><code>Engine position and speed</code> generiert Drehzahlinformationen und Segment-/OT-Interrupts. Die Komponenten <code>Fuel system</code> und <code>Ignition system</code> synchronisieren die Ausgabe der Steuerzeiten winkelsynchron zu den Kurbelwellensegmenten.</p>\n<ol class=\"fig-list\">\n<li><strong>Thermisches Feedback:</strong></li>\n</ol>\n<p class=\"fig-p\"><code>Thermal management</code> und <code>Engine Temperature</code> tauschen kontinuierlich Grenzwerte und Leistungsanforderungen aus, um Bauteilschutzfunktionen (Derating) im Momentenpfad auszulösen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Status der Spezifikation:</strong> <code>AUTOSAR_EXP_AIPowertrain</code> ist ein informativer Erläuterungsbericht (Explanation, <em>EXP</em>), keine normative Software-Spezifikation (<em>SWS</em>). Die Komponentenaufteilung dient als herstellerübergreifende Referenzarchitektur für AUTOSAR Application Interfaces (<code>AI</code>).</li>\n<li><strong>SW-C-Implementierung & Port-Typen:</strong></li>\n<li><code>Engine torque &amp; mode management</code> ist als <code>ApplicationSwComponentType</code> zu modellieren. Die Eingangsschnittstellen (<code>Engine Torque Requests</code>, <code>Engine Speed set-point</code>) basieren auf <code>SenderReceiverInterface</code>.</li>\n<li><code>Engine Mode Request(s)</code> ist bevorzugt als <code>ModeSwitchInterface</code> unter Verwendung definierter <code>ModeDeclarationGroups</code> auszugestalten.</li>\n<li><strong>Echtzeit- und BSW-Konfiguration (MCAL/CDD):</strong></li>\n<li>Die Komponenten <code>Engine position and speed</code>, <code>Fuel system</code> und <code>Ignition system</code> können aufgrund harter Winkelsynchronität und Latenzanforderungen (< 10 µs) in der Regel nicht rein über den Standard-MCAL-Stack (GPT/ICU/PWM) abgebildet werden.</li>\n<li>Entwickler müssen diese Pfade typischerweise an <code>Complex Device Drivers</code> (CDD) oder dedizierte Timer-Coprogressoren (z. B. Bosch GTM, Freescale eTPU) anbinden.</li>\n<li><strong>Multi-Core-Partitionierung:</strong></li>\n</ul>\n<p class=\"fig-p\">Zur Vermeidung von Race Conditions und Dateninkonsistenzen (Data Consistency via RTE) muss die Zerlegung zwischen dem zeitsynchronen Momentenmanagement (<code>Engine torque &amp; mode management</code>) und den winkelsynchronen Aktuator-SW-Cs über Inter-Runnable-Variables (<code>IRV</code>) oder gepufferte RTE-Kommunikation (<code>Queued/Implicit Buffer</code>) thread-sicher ausgelegt werden.</p>"}, {"id": "FIG-1964430c26410c33", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Funktionales Blockdiagramm / Dekompositionsdiagramm der Anwendungsarchitektur (AUTOSAR Application Layer Decomposition).</li>\n<li><strong>Funktionale Einordnung:</strong> Detaillierung der Subdomäne Verbrennungsmotor (<em>Combustion Engine</em>) im Kontext des Dokuments <code>AUTOSAR_EXP_AIPowertrain</code> (R4.0.3). Es definiert die standardisierte funktionale Zerlegung und die Schnittstellen-Entkopplung zwischen der übergeordneten Antriebsstrangkoordination (<em>Power Train Coordinator</em>) und den motorspezifischen Teilsystemen zur Drehmoment-, Drehzahl- und Modusführung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Funktionsblöcke</p>\n<ul class=\"fig-list\">\n<li><strong><code>Power Train Coordinator</code> (PT Coordinator):</strong></li>\n</ul>\n<p class=\"fig-p\">Übergeordnete Koordinationsinstanz für Priorisierung, Optimierung und Verteilung fahrzeugweiter Anforderungen. Beinhaltet drei logische Funktionseinheiten:</p>\n<ul class=\"fig-list\">\n<li><code>PT Torque Coordinator</code>: Schiedsstelle für alle Drehmomentanforderungen (Fahrerwunsch, Fahrwerk/ESP, Getriebe, ACC).</li>\n<li><code>PT Speed Coordinator</code>: Schiedsstelle für Solldrehzahlen (z. B. Leerlaufregelung, Anlassvorgang, Getriebeeingriffe).</li>\n<li><code>PT Operation Mode</code>: Zustandsverwaltung des Gesamtantriebsstrangs (Stopp, Start, Übergangs- und Notlaufmodi).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>Combustion Engine</code> (Domain-Composition):</strong></li>\n</ul>\n<p class=\"fig-p\">Zusammenfassung aller innermotorischen Software-Komponenten (<code>SW-C</code>).</p>\n<ul class=\"fig-list\">\n<li><code>Engine torque &amp; mode management</code>: Zentraler Aggregatsmanager; empfängt und arbitriert die Anforderungen des PT Coordinators und splittet diese in motorische Stellpfade.</li>\n<li>Stellpfad-Subsysteme:</li>\n<li><code>Air system</code>: Steuerung des Füllungspfads (Drosselklappe, variable Steuerzeiten/VVT, Ladedruckregelung, AGR).</li>\n<li><code>Fuel system</code>: Gemischbildung und Einspritzsteuerung (Raildruck, Einspritzzeitpunkt/-dauer, Mehrfacheinspritzung).</li>\n<li><code>Ignition system</code>: Zündungsregelung (Zündzeitpunkt, Schließwinkel/Dwell Time, Zündenergie).</li>\n<li>Autarke/unterstützende Motorsystem-SW-Cs:</li>\n<li><code>Combustion</code>: Zylinderdruckanalyse, Klopfregelung, Verbrennungsdiagnose.</li>\n<li><code>Glow system</code>: Glühzeitsteuerung (insb. Dieselapplikation).</li>\n<li><code>Exhaust system</code>: Abgasnachbehandlung (SCR, Partikelfilter, Katalysatorheizen, Lambdaregelung).</li>\n<li><code>Engine position and speed</code>: Signalverarbeitung Kurbel-/Nockenwelle, Phasenerkennung, Kurbelwinkel-Synchronisation.</li>\n<li><code>Engine Lubrication</code>: Öldruck- und Ölpumpenmanagement.</li>\n<li><code>Engine Temperature</code>: Erfassung und Regelung der innermotorischen thermischen Zustände.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>Thermal management</code> (Externes Subsystem):</strong></li>\n</ul>\n<p class=\"fig-p\">Fahrzeugweites Thermomanagement (Aktoren: <em>water pump</em>, <em>climate compr.</em>); Schnittstelle zur Komponente <code>Engine Temperature</code>.</p>\n<p class=\"fig-p\">#### Schnittstellen & Kommunikationsbeziehungen</p>\n<ul class=\"fig-list\">\n<li><strong>PT Coordinator $\\rightarrow$ Combustion Engine (<code>Engine torque &amp; mode management</code>):</strong></li>\n<li><code>Engine Torque Requests</code>: Sender-Receiver-Schnittstelle zur Übertragung koordinierter Drehmoment-Sollwerte (typisch: physikalische Drehmomentstruktur in Nm, Min-/Max-Grenzen, Prioritäten).</li>\n<li><code>Engine Speed set-point</code>: Sender-Receiver-Schnittstelle für Soll-Drehzahlen.</li>\n<li><code>Engine Mode Request(s)</code>: Mode-Switch- oder Sender-Receiver-Schnittstelle zur Vorgabe diskreter Motorbetriebsmodi.</li>\n<li><strong><code>Engine torque &amp; mode management</code> $\\rightarrow$ Aktuatorpfade:</strong></li>\n<li>Gerichtet aufgeteilt in <code>Air system</code> (langsamer Drehmomentpfad / Füllung), <code>Fuel system</code> und <code>Ignition system</code> (schnelle Drehmomentpfade / Zündwinkel- und Einspritzwirkungsgrad).</li>\n<li><strong><code>Thermal management</code> $\\rightarrow$ <code>Engine Temperature</code>:</strong></li>\n<li>Unidirektionaler Datenfluss zur Abstimmung der Kühlmittelflussanforderungen und Berücksichtigung von thermischen Lastgrenzen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Sollwert-Vorgabe (zyklisch, zeitsynchron, typisch 10 ms):</strong></li>\n</ol>\n<p class=\"fig-p\"><code>PT Torque Coordinator</code>, <code>PT Speed Coordinator</code> und <code>PT Operation Mode</code> konsolidieren externe Anforderungen und stellen konsistente Solldaten an den Ports bereit.</p>\n<ol class=\"fig-list\">\n<li><strong>Arbitrierung & Strukturierung (zeitsynchron):</strong></li>\n</ol>\n<p class=\"fig-p\"><code>Engine torque &amp; mode management</code> empfängt die Anforderungen über die AUTOSAR-RTE, wendet motorspezifische Schutz- und Emissionsbegrenzungen an und teilt das Zieldrehmoment auf:</p>\n<ul class=\"fig-list\">\n<li><em>Langsamer Pfad:</em> Vorsteuerung und Sollwertberechnung für das <code>Air system</code> zur Bereitstellung der Zylinderfüllung.</li>\n<li><em>Schneller Pfad:</em> Dynamische Momentenkorrekturen direkt über <code>Fuel system</code> (Ausblendung, Einspritzmenge) und <code>Ignition system</code> (Zündwinkelverstellung nach spät).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisation mit Motorzyklus (ereignisgesteuert / kurbelwinkelsynchron):</strong></li>\n</ol>\n<p class=\"fig-p\"><code>Engine position and speed</code> generiert Drehzahlinformationen und Segment-/OT-Interrupts. Die Komponenten <code>Fuel system</code> und <code>Ignition system</code> synchronisieren die Ausgabe der Steuerzeiten winkelsynchron zu den Kurbelwellensegmenten.</p>\n<ol class=\"fig-list\">\n<li><strong>Thermisches Feedback:</strong></li>\n</ol>\n<p class=\"fig-p\"><code>Thermal management</code> und <code>Engine Temperature</code> tauschen kontinuierlich Grenzwerte und Leistungsanforderungen aus, um Bauteilschutzfunktionen (Derating) im Momentenpfad auszulösen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Status der Spezifikation:</strong> <code>AUTOSAR_EXP_AIPowertrain</code> ist ein informativer Erläuterungsbericht (Explanation, <em>EXP</em>), keine normative Software-Spezifikation (<em>SWS</em>). Die Komponentenaufteilung dient als herstellerübergreifende Referenzarchitektur für AUTOSAR Application Interfaces (<code>AI</code>).</li>\n<li><strong>SW-C-Implementierung & Port-Typen:</strong></li>\n<li><code>Engine torque &amp; mode management</code> ist als <code>ApplicationSwComponentType</code> zu modellieren. Die Eingangsschnittstellen (<code>Engine Torque Requests</code>, <code>Engine Speed set-point</code>) basieren auf <code>SenderReceiverInterface</code>.</li>\n<li><code>Engine Mode Request(s)</code> ist bevorzugt als <code>ModeSwitchInterface</code> unter Verwendung definierter <code>ModeDeclarationGroups</code> auszugestalten.</li>\n<li><strong>Echtzeit- und BSW-Konfiguration (MCAL/CDD):</strong></li>\n<li>Die Komponenten <code>Engine position and speed</code>, <code>Fuel system</code> und <code>Ignition system</code> können aufgrund harter Winkelsynchronität und Latenzanforderungen (< 10 µs) in der Regel nicht rein über den Standard-MCAL-Stack (GPT/ICU/PWM) abgebildet werden.</li>\n<li>Entwickler müssen diese Pfade typischerweise an <code>Complex Device Drivers</code> (CDD) oder dedizierte Timer-Coprogressoren (z. B. Bosch GTM, Freescale eTPU) anbinden.</li>\n<li><strong>Multi-Core-Partitionierung:</strong></li>\n</ul>\n<p class=\"fig-p\">Zur Vermeidung von Race Conditions und Dateninkonsistenzen (Data Consistency via RTE) muss die Zerlegung zwischen dem zeitsynchronen Momentenmanagement (<code>Engine torque &amp; mode management</code>) und den winkelsynchronen Aktuator-SW-Cs über Inter-Runnable-Variables (<code>IRV</code>) oder gepufferte RTE-Kommunikation (<code>Queued/Implicit Buffer</code>) thread-sicher ausgelegt werden.</p>"}], "trans": [{"from": "FIG-905e61b911620c04", "to": "FIG-741895c783a5a6b0", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-741895c783a5a6b0", "to": "FIG-38ad329e6f7ab9b1", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-38ad329e6f7ab9b1", "to": "FIG-1964430c26410c33", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-1964430c26410c33", "to": "FIG-38ad329e6f7ab9b1", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
